<script setup lang="ts">
import OpeningCredit, {type OpeningCredit as CreditSource,type OpeningApplication} from './OpeningCredit.vue';
import {ref,computed,onMounted,watch} from 'vue';
import {useRouter} from 'vue-router';
import {supabase} from '@/lib/supabase';
import {useAuthStore} from '@/stores/auth';
import {useInvoicesStore} from '@/stores/invoices';
import {formatPen,penCents,penDecimal,limaDate,formatDateLima} from '@/lib/financeMoney';
import type {Invoice} from '@/types/domain';
const props=defineProps<{zones:{id:string;name:string}[]}>();
const emit=defineEmits<{pay:[invoice:Invoice];changed:[];receipt:[id:string]}>();
type Cell={month:number;amount:string;paid:string;due:string;state:string;opening?:boolean;overdue:boolean;unreconciled:boolean;promotion:boolean};
type Collection={bucket:string;nextDueDate:string|null;graceEndDate:string|null;eligibleForSuspension:boolean;lastPaymentDate:string|null;daysPastDue?:number};
type Row={id:string;client_id:string;customer:string;contract_number:string;client_code:string;service_type:string;plan:string;monthly_fee:string;status:string;technical_state:string;months:Cell[];billing_modality:string|null;billing_day:number|null;grace_days:number|null;legacy_billing_day:number|null;debt_hold_status:string;is_courtesy:boolean;courtesy_reason:string|null;last_payment_date:string|null;collection:Collection|null};
type Matrix={rows:Row[];total:number;totals:{billed:string;paid:string;due:string;received:string};monthlyTotals:{month:number;amount:string;paid:string;due:string}[]};
type Payment={id:string;amount?:string;received?:string;applied?:string;credit_remaining?:string;method:string;reference:string;received_at:string;collector:string;reversed_at:string|null;reversal_reason:string;received_date_only?:boolean};
type AuditEntry={id:string;accion:string;actor_id:string;created_at:string;motivo:string;nuevo:{payload?:Record<string,unknown>;result?:Record<string,unknown>};anterior:Record<string,unknown>|null};
const auth=useAuthStore(),store=useInvoicesStore(),router=useRouter(),admin=computed(()=>['ADMIN','SUPERADMIN'].includes(auth.role??''));
const year=ref(Number(limaDate().slice(0,4))),zone=ref(''),search=ref(''),state=ref(''),page=ref(1),busy=ref(false),error=ref(''),message=ref(''),matrix=ref<Matrix|null>(null);
const labels:Record<string,string>={pagado:'Pagado',parcial:'Parcial',vencido:'Vencido',pendiente:'Pendiente',adelantado:'Adelantado',exonerado:'Exonerado',sin_facturacion:'Sin facturación'};
const modalityLabels:Record<string,string>={adelantado:'Pago adelantado',cumplido:'Pago cumplido'};
const bucketLabels:Record<string,string>={sin_configurar:'Sin evaluar (falta modalidad)',pagado:'Al día',pendiente_futuro:'Al día',vence_hoy:'Debe hoy',en_prorroga:'En prórroga',vencido_sin_prorroga:'Elegible para corte',cortesia:'CORTESÍA'};
const debtHoldLabels:Record<string,string>={none:'',pending:'Corte pendiente (otro criterio)',suspended:'Suspendido'};
// Fase 30: la leyenda mostraba "Al día" dos veces (pagado y pendiente_futuro
// comparten el mismo texto) — se deduplica SOLO para la tira de leyenda;
// bucketLabels no cambia, así que el badge de cada fila sigue distinguiendo
// los estados reales (Debe hoy/Suspendido/Cortesía/En prórroga/Elegible
// para corte siguen todos operativos, sin perder ninguno). Las 3 leyendas
// (estado de factura / modalidad comercial / estado de cobranza) se
// mantienen separadas, cada una en su propio bloque.
const bucketLegendEntries=computed(()=>{const seen=new Set<string>();return (Object.entries(bucketLabels) as [string,string][]).filter(([,label])=>{if(seen.has(label))return false;seen.add(label);return true;});});
const months=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
const methods:Record<string,string>={cash:'Efectivo',yape:'Yape',plin:'Plin',transfer:'Transferencia',other:'Otros'};
async function rpc<T>(name:string,args:Record<string,unknown>):Promise<T>{const r=await supabase.rpc(name,args);if(r.error)throw Error(r.error.message);return r.data as T;}
const args=(n=page.value)=>({p_zone:zone.value,p_year:year.value,p_page:n,p_search:search.value.trim(),p_state:state.value});
async function load(reset=false){if(!zone.value){matrix.value=null;return;}if(reset)page.value=1;busy.value=true;error.value='';try{const requested=args();const data=await rpc<Matrix>('finance_pon_matrix',requested);if(JSON.stringify(requested)===JSON.stringify(args()))matrix.value=data;}catch(e){matrix.value=null;error.value=String(e);}finally{busy.value=false;}}
defineExpose({refresh:load});
onMounted(()=>{zone.value=props.zones[0]?.id??'';if(zone.value)void load();});
watch([zone,year,search,state],()=>{matrix.value=null;page.value=1;});
const openingCredits=ref<CreditSource[]>([]),openingApplications=ref<OpeningApplication[]>([]),billingTermsHistory=ref<AuditEntry[]>([]),courtesyHistory=ref<AuditEntry[]>([]);
async function refreshOpening(){await openCell(current.value!,detailMonth.value);await load();emit('changed');}
const current=ref<Row|null>(null),detailMonth=ref(1),detail=ref<{invoices:Invoice[];payments:Payment[];adjustments:Record<string,unknown>[]} |null>(null),history=ref<Payment[]>([]),detailOpen=ref(false);
async function openCell(row:Row,month:number){current.value=row;detailMonth.value=month;detailOpen.value=true;detail.value=null;error.value='';try{const [d,h]=await Promise.all([rpc<NonNullable<typeof detail.value>>('finance_month_detail',{p_contract:row.id,p_year:year.value,p_month:month}),rpc<{payments:Payment[];openingCredits?:CreditSource[];openingApplications?:OpeningApplication[];audit?:AuditEntry[]}>('finance_history',{p_contract_id:row.id})]);detail.value=d;history.value=h.payments;openingCredits.value=h.openingCredits??[];openingApplications.value=h.openingApplications??[];billingTermsHistory.value=(h.audit??[]).filter(a=>a.accion==='billing_terms');courtesyHistory.value=(h.audit??[]).filter(a=>a.accion==='courtesy_status');}catch(e){error.value=String(e);}}
function pay(i:Invoice){detailOpen.value=false;emit('pay',{...i,service_contracts:{contract_number:current.value?.contract_number} as Invoice['service_contracts']});}
const action=ref(''),operationId=ref(''),reason=ref(''),amount=ref(''),source=ref<Payment|null>(null),options=ref<Invoice[]>([]),selected=ref<string[]>([]),method=ref('cash'),reference=ref('');
async function begin(kind:string,p?:Payment){action.value=kind;operationId.value=crypto.randomUUID();reason.value='';amount.value=kind==='fee'?String(current.value?.monthly_fee??''):String(p?.credit_remaining??'');source.value=p??null;selected.value=[];error.value='';method.value='cash';reference.value='';options.value=[];if(['advance','promo'].includes(kind)&&current.value){try{options.value=(await store.fetchInvoicesByContract(current.value.id)).filter(i=>i.status==='pending'&&i.finance_reconciled).sort((a,b)=>a.period_start.localeCompare(b.period_start));}catch(e){error.value=String(e);}}}
const btModality=ref<'adelantado'|'cumplido'>('adelantado'),btDay=ref(1),btGrace=ref(7);
// El dia de pago legacy (service_contracts.billing_day, fase 2/119) solo se
// SUGIERE para precargar el formulario - nunca se confirma ni se escribe
// solo. El admin siempre revisa y confirma explicitamente al guardar.
function beginBillingTerms(){action.value='billing_terms';operationId.value=crypto.randomUUID();reason.value='';error.value='';btModality.value=(current.value?.billing_modality as 'adelantado'|'cumplido')??'adelantado';btDay.value=current.value?.billing_day??current.value?.legacy_billing_day??1;btGrace.value=current.value?.grace_days??7;}
// Vista anual completa vs. 4 meses (anterior/actual/2 siguientes) - mismo
// mes de hoy en America/Lima, nunca el huso horario del dispositivo.
const fullYearView=ref(false);
const currentMonth=computed(()=>Number(limaDate().slice(5,7)));
const visibleMonthIndexes=computed(()=>{if(fullYearView.value)return months.map((_,i)=>i);const start=Math.max(0,Math.min(8,currentMonth.value-2));return [start,start+1,start+2,start+3];});
async function confirmBillingTerms(){if(busy.value||!current.value)return;error.value='';if(reason.value.trim().length<5){error.value='Indica un motivo de al menos cinco caracteres.';return;}busy.value=true;try{await rpc('finance_set_billing_terms',{p_operation_id:operationId.value,p_contract_id:current.value.id,p_modality:btModality.value,p_billing_day:btDay.value,p_grace_days:btGrace.value,p_reason:reason.value.trim()});action.value='';message.value='Condiciones comerciales actualizadas y auditadas.';await load();current.value=matrix.value?.rows.find(r=>r.id===current.value?.id)??current.value;await openCell(current.value!,detailMonth.value);emit('changed');}catch(e){error.value=String(e);}finally{busy.value=false;}}
// Reutiliza is_courtesy/courtesy_reason (fase 47) ya existente en el
// contrato - esta vía queda como la confirmacion/correccion AUDITADA para
// uso financiero (responsable, motivo, fecha, valor anterior/nuevo), nunca
// un campo nuevo duplicado. El toggle inicial puede seguir haciéndose desde
// la ficha general del cliente; cualquier cambio desde Facturación pasa por
// aquí para dejar rastro.
const ctIsCourtesy=ref(false);
function beginCourtesy(){action.value='courtesy_status';operationId.value=crypto.randomUUID();reason.value='';error.value='';ctIsCourtesy.value=!(current.value?.is_courtesy??false);}
async function confirmCourtesy(){if(busy.value||!current.value)return;error.value='';if(reason.value.trim().length<5){error.value='Indica un motivo de al menos cinco caracteres.';return;}busy.value=true;try{await rpc('finance_set_courtesy',{p_operation_id:operationId.value,p_contract_id:current.value.id,p_is_courtesy:ctIsCourtesy.value,p_reason:reason.value.trim()});action.value='';message.value=ctIsCourtesy.value?'Cortesía confirmada y auditada.':'Cortesía retirada y auditada.';await load();current.value=matrix.value?.rows.find(r=>r.id===current.value?.id)??current.value;await openCell(current.value!,detailMonth.value);emit('changed');}catch(e){error.value=String(e);}finally{busy.value=false;}}
const promoTotal=computed(()=>{const selectedRows=options.value.filter(i=>selected.value.includes(i.id)).sort((a,b)=>a.period_start.localeCompare(b.period_start));return penDecimal(selectedRows.slice(0,3).reduce((n,i)=>n+penCents(i.amount_due),0));});
async function confirm(){if(busy.value||!current.value)return;error.value='';if(reason.value.trim().length<5){error.value='Indica un motivo de al menos cinco caracteres.';return;}busy.value=true;try{const common={p_operation_id:operationId.value,p_reason:reason.value.trim()};if(action.value==='reverse'){await rpc('finance_reverse_payment',{...common,p_payment_id:source.value?.id});}else if(action.value==='advance'){await rpc('finance_apply_advance',{...common,p_payment_id:source.value?.id,p_invoice_ids:selected.value,p_amount:penDecimal(penCents(amount.value))});}else if(action.value==='promo'){if(selected.value.length!==4)throw Error('Selecciona exactamente cuatro mensualidades consecutivas.');await rpc('finance_promo_3_1',{...common,p_contract_id:current.value.id,p_invoice_ids:selected.value,p_method:method.value,p_reference:reference.value||null});}else{await rpc('finance_set_monthly_fee',{...common,p_contract_id:current.value.id,p_amount:penDecimal(penCents(amount.value))});}action.value='';message.value='Operación financiera confirmada y auditada.';await load();current.value=matrix.value?.rows.find(r=>r.id===current.value?.id)??current.value;await openCell(current.value,detailMonth.value);emit('changed');}catch(e){error.value=String(e);}finally{busy.value=false;}}
const date=(value:string)=>new Date(value).toLocaleString('es-PE',{timeZone:'America/Lima'});
async function exportCsv(){if(!matrix.value||busy.value)return;busy.value=true;try{if(matrix.value.total>5000)throw Error('Acota la búsqueda a un máximo de 5000 contratos.');const parameters=args();const rows:Row[]=[];for(let n=1;n<=Math.ceil(matrix.value.total/25);n++)rows.push(...(await rpc<Matrix>('finance_pon_matrix',{...parameters,p_page:n})).rows);const header=['Cliente','Cintillo','Contrato','Servicio','Plan','Mensualidad PEN','Estado comercial','Estado técnico',...months.flatMap(m=>[m+' importe',m+' pagado',m+' saldo',m+' estado'])];const safe=(v:unknown)=>'"'+String(v??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';const data=rows.map(r=>[r.customer,r.client_code,r.contract_number,r.service_type,r.plan,r.monthly_fee,r.status,'Sin verificar',...r.months.flatMap(c=>[c.amount,c.paid,c.due,labels[c.state]])]);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\uFEFF'+[header,...data].map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));a.download=`cobranza-pon-${year.value}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}catch(e){error.value=String(e);}finally{busy.value=false;}}
</script>
<template>
 <section class="pon-workspace"><div class="finance-table-tools"><h2>Cobranza por PON</h2><button class="btn-ghost" @click="fullYearView=!fullYearView">{{fullYearView?'Ver 4 meses (anterior/actual/próximos)':'Ver año completo'}}</button><button class="btn-ghost" :disabled="busy||!matrix" @click="exportCsv">Exportar PON a Excel (CSV)</button></div>
 <form class="finance-filters" @submit.prevent="load(true)"><label>PON / zona<select v-model="zone" aria-label="PON de cobranza"><option value="">Seleccionar zona</option><option v-for="z in zones" :key="z.id" :value="z.id">{{z.name}}</option></select></label><label>Año<input v-model.number="year" type="number" min="2020" max="2100" aria-label="Año de matriz"></label><label>Buscar<input v-model="search" maxlength="100" placeholder="Cliente, DNI, contrato o cintillo" aria-label="Buscar en PON"></label><label>Estado financiero<select v-model="state"><option value="">Todos</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select></label><button class="btn-secondary" :disabled="busy">{{busy?'Consultando…':'Buscar'}}</button></form>
 <p class="finance-help">Mensualidades por inicio de período · saldos actuales · una fila por contrato. Una celda sin facturación no acredita deuda. El estado técnico se verifica por separado.</p>
 <p v-if="error" role="alert" class="finance-error">{{error}}</p><p v-if="message" role="status" class="finance-notice">{{message}}</p>
 <template v-if="matrix"><div class="pon-totals"><span>Emitido <b>{{formatPen(matrix.totals.billed)}}</b></span><span>Aplicado a mensualidades <b>{{formatPen(matrix.totals.paid)}}</b></span><span>Saldo <b>{{formatPen(matrix.totals.due)}}</b></span><span>Caja neta del año <b>{{formatPen(matrix.totals.received)}}</b></span></div>
 <div class="pon-legend"><span v-for="(label,key) in labels" :key="key" :class="['pon-state',key]">{{label}}</span></div>
 <p class="finance-help">Modalidad comercial (azul/verde) y estado de cobranza son indicadores independientes del estado de la factura de arriba.</p>
 <div class="pon-legend"><span class="pon-modalidad adelantado">Pago adelantado</span><span class="pon-modalidad cumplido">Pago cumplido</span><span class="pon-modalidad sin-configurar">Sin configurar</span><span class="pon-modalidad cortesia">Cortesía</span><span v-for="[key,label] in bucketLegendEntries" :key="key" :class="['pon-cobro',key]">{{label}}</span><span class="pon-cobro suspended">Suspendido</span></div>
 <div class="pon-scroll" tabindex="0" aria-label="Matriz de cobranza"><table class="pon-matrix"><thead><tr><th class="pon-name">Cliente / cintillo</th><th class="pon-contract">Contrato / servicio</th><th v-for="i in visibleMonthIndexes" :key="i" :class="{'pon-month-current':i+1===currentMonth}">{{months[i]}}</th></tr></thead><tbody><tr v-for="r in matrix.rows" :key="r.id"><th class="pon-name"><button class="pon-contract-open" @click="router.push(`/clientes/${r.client_id}/servicios/${r.id}`)">{{r.customer}}</button><small>{{r.client_code||'Sin cintillo'}}</small></th><th class="pon-contract"><button class="pon-contract-open" @click="openCell(r,detailMonth)">{{r.contract_number}}</button><small>{{r.plan}} · {{formatPen(r.monthly_fee)}}</small><small>{{r.service_type==='solo_iptv'?'IPTV':'Paquete Internet'}} · Comercial: {{r.status}}</small>
  <div class="pon-badges"><span :class="['pon-modalidad',r.is_courtesy?'cortesia':(r.billing_modality||'sin-configurar')]">{{r.is_courtesy?'Cortesía':(r.billing_modality?modalityLabels[r.billing_modality]:(r.legacy_billing_day?`Día ${r.legacy_billing_day} sin confirmar`:'Sin configurar'))}}</span><span v-if="r.collection" :class="['pon-cobro',r.collection.bucket]">{{bucketLabels[r.collection.bucket]}}</span><span v-if="r.debt_hold_status==='suspended'" class="pon-cobro suspended">{{debtHoldLabels.suspended}}</span></div>
  <small v-if="r.is_courtesy">{{r.courtesy_reason||'Servicio gratuito confirmado'}}</small>
  <small v-else-if="r.collection?.nextDueDate">Próx. vencimiento {{formatDateLima(r.collection.nextDueDate)}}<template v-if="r.collection.graceEndDate"> · prórroga hasta {{formatDateLima(r.collection.graceEndDate)}}</template></small></th><td v-for="i in visibleMonthIndexes" :key="i"><button :class="['pon-cell',r.months[i].state]" @click="openCell(r,r.months[i].month)"><span>{{r.months[i].state==='sin_facturacion'?'—':formatPen(r.months[i].due==='0.00'||Number(r.months[i].due)===0?r.months[i].amount:r.months[i].due)}}</span><small>{{labels[r.months[i].state]}}{{r.months[i].overdue&&r.months[i].state==='parcial'?' / vencido':''}}{{r.months[i].promotion?' · 3+1':''}}</small><small v-if="r.months[i].opening">Saldo inicial conciliado</small><small v-if="r.months[i].unreconciled">No conciliada</small></button></td></tr><tr v-if="!matrix.rows.length"><td colspan="6">Sin contratos para estos filtros.</td></tr></tbody><tfoot><tr><th class="pon-name">Saldo total PON</th><th class="pon-contract">{{matrix.total}} contratos filtrados</th><td v-for="i in visibleMonthIndexes" :key="i">{{formatPen(matrix.monthlyTotals[i]?.due??'0')}}</td></tr></tfoot></table></div>
 <div class="finance-pagination"><span>{{matrix.total}} contratos · página {{page}} · 25 filas</span><button :disabled="busy||page===1" @click="page--;load()">Anterior</button><button :disabled="busy||page*25>=matrix.total" @click="page++;load()">Siguiente</button></div></template>
 <p v-else-if="!busy" class="finance-empty">Selecciona una PON/zona real para consultar sus contratos.</p>
 </section>
 <Teleport to="body"><div v-if="detailOpen" class="modal-overlay"><section class="modal-panel finance-dialog" role="dialog" aria-modal="true"><div class="finance-dialog-head"><h2>{{current?.contract_number}} · {{months[detailMonth-1]}} {{year}}</h2><button aria-label="Cerrar mensualidad" :disabled="busy" @click="detailOpen=false;action=''">×</button></div><p>{{current?.customer}} · {{current?.client_code}} · {{current?.plan}}</p><p class="finance-help">Comercial: {{current?.status}} · Técnico: sin verificar. Ninguna operación financiera ejecuta acciones de red.</p>
 <section v-if="current" class="billing-terms"><h3>Condiciones comerciales</h3>
  <template v-if="current.is_courtesy"><p><b class="pon-modalidad cortesia">Cortesía</b> · servicio gratuito confirmado</p><p class="finance-help">{{current.courtesy_reason||'Sin motivo registrado'}}. No se factura cobro, no cuenta como deuda/mora y no es elegible para corte mientras la cortesía esté activa.</p></template>
  <template v-else>
  <p v-if="current.billing_modality"><b :class="['pon-modalidad',current.billing_modality]">{{modalityLabels[current.billing_modality]}}</b> · día de pago {{current.billing_day}}<template v-if="current.billing_modality==='adelantado'"> · {{current.grace_days}} días de prórroga</template></p>
  <p v-else class="finance-help">Sin configurar: el administrador todavía no definió la modalidad comercial. El sistema nunca asume "adelantado" por defecto.<template v-if="current.legacy_billing_day"> El contrato ya tiene registrado el día {{current.legacy_billing_day}} como día de emisión (dato existente, reutilizable al confirmar) — todavía falta decidir la modalidad (adelantado/cumplido) para activar la cobranza.</template></p>
  <p v-if="current.collection"><span :class="['pon-cobro',current.collection.bucket]">{{bucketLabels[current.collection.bucket]}}</span><template v-if="current.collection.nextDueDate"> · próximo vencimiento {{formatDateLima(current.collection.nextDueDate)}}</template><template v-if="current.collection.graceEndDate"> · fin de prórroga {{formatDateLima(current.collection.graceEndDate)}}</template></p>
  </template>
  <p class="finance-help">Indicador informativo según modalidad/vencimiento (fase 7C) — nunca ejecuta cortes ni reconexiones.{{current.debt_hold_status==='suspended'?' Estado real de suspensión (Cortes por deuda): Suspendido.':''}}</p>
  <div class="finance-shortcuts">
   <button v-if="admin&&!current.is_courtesy" class="btn-ghost" :disabled="busy" @click="beginBillingTerms">Editar condiciones comerciales</button>
   <button v-if="admin" class="btn-ghost" :disabled="busy" @click="beginCourtesy">{{current.is_courtesy?'Quitar cortesía':'Marcar como cortesía'}}</button>
  </div>
  <form v-if="action==='billing_terms'" class="pon-operation" @submit.prevent="confirmBillingTerms"><h4>Nuevas condiciones comerciales</h4><div class="finance-form-grid"><label>Modalidad<select v-model="btModality"><option value="adelantado">Pago adelantado (con prórroga)</option><option value="cumplido">Pago cumplido (sin prórroga)</option></select></label><label>Día de pago (1-31)<input v-model.number="btDay" type="number" min="1" max="31" required></label><label v-if="btModality==='adelantado'">Días de prórroga<input v-model.number="btGrace" type="number" min="0" max="60" required></label><label>Motivo<input v-model="reason" required minlength="5" maxlength="500"></label></div><p v-if="error" role="alert" class="finance-error">{{error}}</p><div class="finance-dialog-actions"><button type="button" class="btn-ghost" :disabled="busy" @click="action=''">Cancelar</button><button class="btn-primary" :disabled="busy">Confirmar condiciones comerciales</button></div></form>
  <form v-if="action==='courtesy_status'" class="pon-operation" @submit.prevent="confirmCourtesy"><h4>{{ctIsCourtesy?'Confirmar servicio gratuito (cortesía)':'Quitar cortesía: el servicio vuelve a facturarse'}}</h4><div class="finance-form-grid"><label>Motivo<input v-model="reason" required minlength="5" maxlength="500" placeholder="Ej. módem de oficina, familiar con beneficio"></label></div><p v-if="error" role="alert" class="finance-error">{{error}}</p><div class="finance-dialog-actions"><button type="button" class="btn-ghost" :disabled="busy" @click="action=''">Cancelar</button><button class="btn-primary" :disabled="busy">Confirmar y auditar</button></div></form>
  <details v-if="billingTermsHistory.length" class="billing-terms-history"><summary>Historial de condiciones comerciales ({{billingTermsHistory.length}})</summary><p v-for="h in billingTermsHistory" :key="h.id" class="finance-history-line">{{date(h.created_at)}} · {{modalityLabels[String(h.nuevo.payload?.modality)]||h.nuevo.payload?.modality}} · día {{h.nuevo.payload?.billingDay}}<template v-if="h.nuevo.payload?.graceDays!=null"> · {{h.nuevo.payload?.graceDays}} días de prórroga</template><small>{{h.motivo}}</small></p></details>
  <details v-if="courtesyHistory.length" class="billing-terms-history"><summary>Historial de cortesía ({{courtesyHistory.length}})</summary><p v-for="h in courtesyHistory" :key="h.id" class="finance-history-line">{{date(h.created_at)}} · {{h.nuevo.payload?.isCourtesy?'Confirmada':'Retirada'}}<small>{{h.motivo}}</small></p></details>
 </section>
 <p v-if="error" role="alert" class="finance-error">{{error}}</p><p v-if="!detail">Cargando mensualidad…</p><template v-else><p v-if="!detail.invoices.length">Sin facturación en este mes. No se presume deuda.</p><div v-for="i in detail.invoices" :key="i.id" class="finance-history-line"><b>{{i.invoice_number}}</b> · {{i.period_start}}<p>Emitido {{formatPen(i.amount)}} · Pagado {{formatPen(i.amount_paid)}} · Saldo {{formatPen(i.amount_due)}}</p><button v-if="i.status==='pending'" class="btn-primary" @click="pay(i)">Registrar pago</button><small v-if="!i.finance_reconciled">No conciliada: cobro bloqueado por el servidor.</small></div>
 <h3>Movimientos de la mensualidad</h3><p v-for="(p,n) in detail.payments" :key="p.id+'-'+n" class="finance-history-line">{{p.received_date_only?new Date(p.received_at).toLocaleDateString('es-PE',{timeZone:'America/Lima'}):date(p.received_at)}} · Aplicado {{formatPen(p.applied)}} · {{methods[p.method]}} · {{p.reference||'Sin referencia'}}<button class="finance-link" @click="emit('receipt',p.id)">Ver / descargar recibo</button><small>{{p.collector}} · {{p.reversed_at?'REVERSADO: '+p.reversal_reason:'Vigente'}}</small></p><p v-for="(a,n) in detail.adjustments" :key="n">{{a.tipo}} · {{formatPen(String(a.monto))}} · {{a.reversed_at?'Revertido':'Sin ingreso de caja'}}</p>
 <OpeningCredit :credits="openingCredits" :applications="openingApplications" :invoices="detail.invoices" :admin="admin" @changed="refreshOpening"/><h3>Historial de pagos del contrato</h3><div v-for="p in history" :key="p.id" class="finance-history-line">{{p.received_date_only?new Date(p.received_at).toLocaleDateString('es-PE',{timeZone:'America/Lima'}):date(p.received_at)}} · {{formatPen(p.amount)}} · {{methods[p.method]}}<small>{{p.collector}} · {{p.reference}} · {{p.reversed_at?'Reversado':'Vigente'}}</small><button v-if="admin&&!p.reversed_at" class="finance-link danger" @click="begin('reverse',p)">Reversar pago</button><button v-if="!p.reversed_at&&Number(p.credit_remaining)>0" class="finance-link" @click="begin('advance',p)">Aplicar anticipo {{formatPen(p.credit_remaining)}}</button></div><p class="finance-help">Hasta 100 pagos. Cada reverso conserva el movimiento original y requiere motivo.</p>
 <div v-if="admin" class="finance-shortcuts"><button @click="begin('fee')">Mensualidad personalizada</button><button @click="begin('promo')">Preparar promoción 3+1</button></div>
 <form v-if="action&&action!=='billing_terms'" class="pon-operation" @submit.prevent="confirm"><h3>{{({reverse:'Confirmar reversión',advance:'Aplicar saldo adelantado',promo:'Tres meses pagados + cuarto gratis',fee:'Mensualidad futura personalizada'} as Record<string,string>)[action]}}</h3><p v-if="action==='reverse'">Se reversará el pago completo de {{formatPen(source?.amount)}}. No se borra su historial.</p><p v-if="action==='promo'">Selecciona cuatro facturas mensuales futuras, consecutivas y del mismo importe. Cobro: {{formatPen(promoTotal)}}; el cuarto mes es una promoción sin dinero recibido. Reglas conservadoras pendientes de validación comercial.</p><div v-if="action==='advance'||action==='promo'" class="finance-invoice-options"><label v-for="i in options" :key="i.id"><input v-model="selected" type="checkbox" :value="i.id"><span>{{i.period_start}} · {{i.invoice_number}}</span><b>{{formatPen(i.amount_due)}}</b></label></div><div class="finance-form-grid"><label v-if="action==='advance'||action==='fee'">Importe PEN<input v-model="amount" inputmode="decimal" required></label><template v-if="action==='promo'"><label>Método<select v-model="method"><option v-for="(label,key) in methods" :key="key" :value="key">{{label}}</option></select></label><label>Número de operación<input v-model="reference" maxlength="100"></label></template><label>Motivo<input v-model="reason" required minlength="5" maxlength="500"></label></div><p v-if="error" role="alert" class="finance-error">{{error}}</p><div class="finance-dialog-actions"><button type="button" class="btn-ghost" :disabled="busy" @click="action=''">Cancelar</button><button class="btn-primary" :disabled="busy">Confirmar operación auditada</button></div></form></template></section></div></Teleport>
